    let mut seen: HashMap<&str, usize> = HashMap::new();
    let mut out = Vec::new();
    for part in input.split(',').map(str::trim).filter(|p| !p.is_empty()) {
        let count = seen.entry(part).or_insert(0);
        *count += 1;
        if *count == 1 && out.len() < limit { out.push(format!("{}:index", part)); }
