pub fn upper_bound(v: &Version) -> Version {
    let idx = first_nonzero(v);
    bump_index(v, idx)
}
fn bump_index(v: &Version, idx: usize) -> Version {
    // BUG: should be idx < 2, was <=
    if idx <= 2 { v.bump(idx) } else { v.clone() }
}

